10	// 计划状态：进行中的计划可改期、取消或完成；已完成与已取消均为终态，
11	// 不能再改期、取消或重新开启。
12	const (
13		PlanStatusOpen     = "未完成"
14		PlanStatusDone     = "已完成"
15		PlanStatusCanceled = "已取消"
16	)
17	
18	// 待办相对本机今天的标记。
19	const (
20		TodoToday   = "今天需校准"
21		TodoOverdue = "逾期"
22		TodoFuture  = "未到计划日"
23	)
24	
25	// PlanChange 记录一次改期：保留修改前后的日期、操作时间和原因。
26	type PlanChange struct {
27		From      string `json:"from"`
28		To        string `json:"to"`
29		ChangedAt string `json:"changed_at"`
30		Reason    string `json:"reason"`
31	}
32	
33	// Plan 是一项校准计划。编号在全台账唯一，即使计划已结束编号也不再复用。
34	type Plan struct {
35		Number       string `json:"number"`
36		InstrumentID string `json:"instrument_id"`
37		// PlannedDate 是当前计划日期；OriginalDate 保留建立时的计划日期。
38		PlannedDate  string       `json:"planned_date"`
39		OriginalDate string       `json:"original_date"`
40		Note         string       `json:"note"`
41		CreatedAt    string       `json:"created_at"`
42		Changes      []PlanChange `json:"changes,omitempty"`
43		Status       string       `json:"status"`
44		// 取消时保留原计划日期、取消时间和原因。
45		CanceledAt   string `json:"canceled_at,omitempty"`
46		CancelReason string `json:"cancel_reason,omitempty"`
47		// 完成时保存完成时间和所用证书编号。
48		CompletedAt       string `json:"completed_at,omitempty"`
49		CertificateNumber string `json:"certificate_number,omitempty"`
50	}
