100	// validatePlanDate 解析 YYYY-MM-DD 真实日期，且不得早于本机今天。
101	func (l *Ledger) validatePlanDate(raw, field string) (string, error) {
102		_, text, err := parseFiniteDate(raw, field)
103		if err != nil {
104			return "", err
105		}
106		todayText := l.now().Format(DateLayout)
107		if text < todayText {
108			return "", validationError("%s %s 不能早于本机今天 %s", field, text, todayText)
109		}
110		return text, nil
111	}
