113	// CreatePlan 为已登记器具建立一项校准计划。计划编号全台账唯一（即使对应
114	// 已结束计划也不能复用），计划日期须真实存在且不早于本机今天，说明非空；
115	// 每件器具最多有一项未完成、未取消的计划。任一条件不满足都明确拒绝，
116	// 不新增或改动任何记录。
117	//
118	// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
119	// 台账（含同一对象随后的计划查询、按器具核对与待办）与建立前完全一致——
120	// 失败的计划既不占用编号，也不占用该器具唯一的未结束计划名额，更不会在此后
121	// 其他成功操作写盘时被顺带写入；文件仍不可写时再次提交相同编号仍报保存错误
122	// （不会被当成编号重复或器具已有未结束计划而拒绝），恢复可写后无需重新打开
123	// 台账，重新提交才真正建立，建立时间取本次成功申请的时间。
124	//
125	// 返回的计划只是已保存内容的展示副本，与台账内存储不共享内存：调用方为
126	// 显示而改动编号、日期、状态或关联证书，不占用或释放正式计划编号，不影响
127	// 每件器具最多一项未结束计划的判断，也不会在此后正常写盘时被带入台账文件；
128	// 重新查询同一台账得到的仍是最后成功保存的计划。
129	func (l *Ledger) CreatePlan(in PlanInput) (*Plan, error) {
130		number, err := cleanText(in.Number)
131		if err != nil {
132			return nil, fmt.Errorf("计划编号无效：%w", err)
133		}
134		instID, err := cleanText(in.InstrumentID)
135		if err != nil {
136			return nil, fmt.Errorf("器具编号无效：%w", err)
137		}
138		note, err := cleanText(in.Note)
139		if err != nil {
140			return nil, fmt.Errorf("计划说明无效：%w", err)
141		}
142		if l.findInstrument(instID) == nil {
143			return nil, fmt.Errorf("器具编号 %s：%w", instID, ErrNotFound)
144		}
145		dateText, err := l.validatePlanDate(in.Date, "计划日期")
146		if err != nil {
147			return nil, err
148		}
149		if l.findPlan(number) != nil {
150			return nil, validationError("计划编号 %s 已存在，编号必须全台账唯一且不能复用", number)
151		}
152		for i := range l.data.Plans {
153			p := &l.data.Plans[i]
154			if p.InstrumentID == instID && p.Open() {
155				return nil, validationError(
156					"器具 %s 已有未结束的计划 %s（计划日期 %s），每件器具最多一项未结束计划",
157					instID, p.Number, p.PlannedDate)
158			}
159		}
160		p := Plan{
161			Number:       number,
162			InstrumentID: instID,
163			PlannedDate:  dateText,
164			OriginalDate: dateText,
165			Note:         note,
166			CreatedAt:    l.now().Format(time.RFC3339),
167			Status:       PlanStatusOpen,
168		}
169		// 在独立的新切片上暂存新计划：只有原子替换台账文件成功后才提交。
170		// 写盘失败时恢复原切片，保证同一台账对象随后看到的计划查询、待办与
171		// 按器具核对都与建立前一致——失败计划不占用编号或该器具唯一的未结束
172		// 计划名额，再次提交仍会走到保存而不会被当成重复计划拒绝，失败计划也
173		// 不会被之后的写盘顺带写入。
174		original := l.data.Plans
175		staged := make([]Plan, 0, len(original)+1)
176		staged = append(staged, original...)
177		staged = append(staged, p)
178		l.data.Plans = staged
179		if err := l.save(); err != nil {
180			l.data.Plans = original
181			return nil, err
182		}
183		return clonePlanPtr(l.findPlan(number)), nil
184	}
185	
186	// requireOpenPlan 找到计划并确认其尚未结束；已结束计划返回明确的校验错误。
187	func (l *Ledger) requireOpenPlan(number string) (*Plan, error) {
188		p := l.findPlan(number)
189		if p == nil {
190			return nil, fmt.Errorf("计划编号 %s：%w", number, ErrNotFound)
191		}
192		if !p.Open() {
193			return nil, validationError("计划 %s %s，已结束的计划不能再改期、取消或重新开启",
194				number, p.Status)
195		}
196		return p, nil
197	}
198	
199	// ReschedulePlan 改期一项未结束的计划。原因必须非空，新日期必须真实存在且
200	// 不早于操作当天；每次改期保留修改前后的日期、操作时间和原因。
201	// 找不到计划或计划已结束时拒绝且不改动记录。
202	//
203	// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
204	// 台账（含同一对象随后的核对、计划查询与待办）与改期前完全一致——当前计划
205	// 日期不改变，失败申请的原因和时间既不进入改期历史、不改变待办标记，也不会
206	// 在此后其他成功操作写盘时被顺带写入；恢复可写后重新提交才按当时时间生效，
207	// 且只新增一条从最后成功保存的日期到新日期的记录。
208	//
209	// 返回的计划（含改期历史）是已保存内容的独立展示副本：调用方改动其中的
210	// 当前日期、状态或任意一条改期记录的原因、前后日期、操作时间，调换、删去
211	// 或追加列表记录，都只影响自己手中的那一份，不改写正式计划，也不影响
212	// 此前分别取得的操作结果、计划查询结果和核对结果。
213	func (l *Ledger) ReschedulePlan(number, newDate, reason string) (*Plan, error) {
214		number, err := cleanText(number)
215		if err != nil {
216			return nil, fmt.Errorf("计划编号无效：%w", err)
217		}
218		reason, err = cleanText(reason)
219		if err != nil {
220			return nil, fmt.Errorf("改期原因无效：%w", err)
221		}
222		dateText, err := l.validatePlanDate(newDate, "新计划日期")
223		if err != nil {
224			return nil, err
225		}
226		p, err := l.requireOpenPlan(number)
227		if err != nil {
228			return nil, err
229		}
230		// 即使新日期与当前日期相同也照常记录：保留修改前后的日期、操作时间和原因。
231		change := PlanChange{
232			From:      p.PlannedDate,
233			To:        dateText,
234			ChangedAt: l.now().Format(time.RFC3339),
235			Reason:    reason,
236		}
237		// 在整份计划切片的独立副本上暂存改期：只有原子替换台账文件成功后才提交。
238		// 写盘失败时恢复原切片（含原计划日期与改期历史），保证同一台账对象随后看到的
239		// 计划日期、改期历史与待办标记都与改期前一致，且不会被之后的写盘顺带写入。
240		original := l.data.Plans
241		staged := make([]Plan, len(original))
242		copy(staged, original)
243		for i := range staged {
244			if staged[i].Number != number {
245				continue
246			}
247			staged[i].Changes = append(append([]PlanChange(nil), staged[i].Changes...), change)
248			staged[i].PlannedDate = dateText
249		}
250		l.data.Plans = staged
251		if err := l.save(); err != nil {
252			l.data.Plans = original
253			return nil, err
254		}
255		return clonePlanPtr(l.findPlan(number)), nil
256	}
257	
258	// CancelPlan 取消一项未结束的计划，原因必须非空。取消后保留原计划、取消时间
259	// 和原因，不再列入待办，也不能重新开启。找不到计划或计划已结束时拒绝。
260	//
261	// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
262	// 台账（含同一对象随后的计划查询、按器具核对与待办）与取消前完全一致——
263	// 计划仍为未完成并继续列入待办，取消时间和原因不留下本次申请的内容，也不会
264	// 在此后其他成功操作写盘时被顺带写入；文件仍不可写时再次提交仍报保存错误
265	// （不会被当成“已结束”拒绝），恢复可写后无需重新打开台账，重新提交才真正
266	// 取消，取消时间和原因取本次成功提交而非失败那次。
267	//
268	// 返回的取消结果是独立展示副本：调用方把状态改回未完成或清空取消信息，
269	// 只影响自己那一份，正式计划仍保持已取消且不再列入待办。
270	func (l *Ledger) CancelPlan(number, reason string) (*Plan, error) {
271		number, err := cleanText(number)
272		if err != nil {
273			return nil, fmt.Errorf("计划编号无效：%w", err)
274		}
275		reason, err = cleanText(reason)
276		if err != nil {
277			return nil, fmt.Errorf("取消原因无效：%w", err)
278		}
279		if _, err := l.requireOpenPlan(number); err != nil {
280			return nil, err
281		}
282		canceledAt := l.now().Format(time.RFC3339)
283		// 在整份计划切片的独立副本上暂存取消：只有原子替换台账文件成功后才提交。
284		// 写盘失败时恢复原切片（计划仍为未完成、取消时间与原因为空），保证同一
285		// 台账对象随后看到的计划状态、待办与核对都与取消前一致，再次提交不会被
286		// 当成“已结束”，失败信息也不会被之后的写盘顺带写入。
287		original := l.data.Plans
288		staged := make([]Plan, len(original))
289		copy(staged, original)
290		for i := range staged {
291			if staged[i].Number != number {
292				continue
293			}
294			staged[i].Status = PlanStatusCanceled
295			staged[i].CanceledAt = canceledAt
296			staged[i].CancelReason = reason
297		}
298		l.data.Plans = staged
299		if err := l.save(); err != nil {
300			l.data.Plans = original
301			return nil, err
302		}
303		return clonePlanPtr(l.findPlan(number)), nil
304	}
305	
306	// CompletePlan 用一张台账中已有的证书完成计划。证书必须属于该器具，校准日期
307	// 不得早于计划最初建立的本机日期，且未被用于完成其他计划。符合条件后保存
308	// 完成时间和证书编号；超差证书同样表示校准工作已完成。
309	//
310	// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
311	// 台账（含同一对象随后的计划查询、按器具核对与待办）与完成前完全一致——
312	// 计划仍为未完成并继续列入待办，完成时间与关联证书编号保持操作前的值，
313	// 计划日期、已有改期记录和待办日期标记都不改变，该证书也不会被算作已用于
314	// 完成计划（既不会被随后的提交当成“此前已完成”跳过保存，也不会被其他成功
315	// 写盘顺带写入文件）；恢复可写后无需重新打开台账，重新提交才真正完成，
316	// 完成时间取本次成功操作而非失败时刻。
317	//
318	// 再次用同一证书完成同一已保存为完成的计划返回原结果，不增加记录或刷新
319	// 完成时间；已完成计划改用另一证书、证书不存在或不符合条件、完成已取消
320	// 计划均拒绝。
321	//
322	// 返回的完成结果（含再次完成返回的原结果）是独立展示副本：调用方把它改成
323	// 未完成或换掉证书编号，正式计划仍保持完成，原证书仍算已用于该计划，不能
324	// 因此拿去完成另一项计划，完成时间也不会被刷新。
325	func (l *Ledger) CompletePlan(number, certificateNumber string) (*Plan, bool, error) {
326		number, err := cleanText(number)
327		if err != nil {
328			return nil, false, fmt.Errorf("计划编号无效：%w", err)
329		}
330		certificateNumber, err = cleanText(certificateNumber)
331		if err != nil {
332			return nil, false, fmt.Errorf("证书编号无效：%w", err)
333		}
334		p := l.findPlan(number)
335		if p == nil {
336			return nil, false, fmt.Errorf("计划编号 %s：%w", number, ErrNotFound)
337		}
338		// 幂等：同一证书再次完成同一计划，返回原结果，不刷新完成时间。
339		// 返回的同样是独立副本：即使把它改成未完成或换掉证书编号，正式计划
340		// 仍保持完成、原证书仍算已用于该计划。
341		if p.Status == PlanStatusDone {
342			if p.CertificateNumber == certificateNumber {
343				return clonePlanPtr(p), true, nil
344			}
345			return nil, false, validationError(
346				"计划 %s 已用证书 %s 完成，已完成计划不能改用另一证书",
347				number, p.CertificateNumber)
348		}
349		if p.Status == PlanStatusCanceled {
350			return nil, false, validationError("计划 %s 已取消，取消的计划不能完成；需要继续安排请建立新计划", number)
351		}
352	
353		cert := l.findCertificate(certificateNumber)
354		if cert == nil {
355			return nil, false, fmt.Errorf("证书编号 %s：%w", certificateNumber, ErrNotFound)
356		}
357		if cert.InstrumentID != p.InstrumentID {
358			return nil, false, validationError(
359				"证书 %s 属于器具 %s，不能用于完成器具 %s 的计划 %s",
360				certificateNumber, cert.InstrumentID, p.InstrumentID, number)
361		}
362		// 计划建立的本机日期：CreatedAt 是 RFC3339，取其日历日期；与证书校准日期
363		// 按日历日期比较，校准日期不得早于该日期（等于可以）。
364		created, perr := time.Parse(time.RFC3339, p.CreatedAt)
365		if perr != nil {
366			return nil, false, fmt.Errorf("计划 %s 建立时间已损坏: %w", number, perr)
367		}
368		createdDay := created.Format(DateLayout)
369		if cert.CalDate < createdDay {
370			return nil, false, validationError(
371				"证书 %s 的校准日期 %s 早于计划 %s 的建立日期 %s，不能用于完成该计划",
372				certificateNumber, cert.CalDate, number, createdDay)
373		}
374		// 同一证书不能用于完成两项计划；以幂等方式再次完成本计划已在前面处理。
375		for i := range l.data.Plans {
376			other := &l.data.Plans[i]
377			if other.Number != number && other.Status == PlanStatusDone &&
378				other.CertificateNumber == certificateNumber {
379				return nil, false, validationError(
380					"证书 %s 已用于完成计划 %s，不能再用于完成其他计划",
381					certificateNumber, other.Number)
382			}
383		}
384	
385		completedAt := l.now().Format(time.RFC3339)
386		// 在整份计划切片的独立副本上暂存完成：只有原子替换台账文件成功后才提交。
387		// 写盘失败时恢复原切片（计划仍为未完成、完成时间与关联证书编号为空），
388		// 保证同一台账对象随后看到的计划状态、待办与证书占用都与完成前一致，
389		// 再次提交不会被当成“此前已完成”，失败信息也不会被之后的写盘顺带写入。
390		original := l.data.Plans
391		staged := make([]Plan, len(original))
392		copy(staged, original)
393		for i := range staged {
394			if staged[i].Number != number {
395				continue
396			}
397			staged[i].Status = PlanStatusDone
398			staged[i].CompletedAt = completedAt
399			staged[i].CertificateNumber = certificateNumber
400		}
401		l.data.Plans = staged
402		if err := l.save(); err != nil {
403			l.data.Plans = original
404			return nil, false, err
405		}
406		return clonePlanPtr(l.findPlan(number)), false, nil
407	}
408	
409	// TodoItem 是待办查询中的一项计划及其按本机日期重新判断的标记。
410	type TodoItem struct {
411		PlanNumber     string `json:"plan_number"`
412		InstrumentID   string `json:"instrument_id"`
413		InstrumentName string `json:"instrument_name"`
414		Status         Status `json:"status"`
415		PlannedDate    string `json:"planned_date"`
416		Note           string `json:"note"`
417		Marker         string `json:"marker"`
418	}
419	
420	// planMarker 按计划日期相对今天给出标记：今天“今天需校准”，已过“逾期”，
421	// 未来“未到计划日”。
422	func planMarker(plannedDate, todayText string) string {
423		switch {
424		case plannedDate < todayText:
425			return TodoOverdue
426		case plannedDate == todayText:
427			return TodoToday
428		default:
429			return TodoFuture
430		}
431	}
432	
433	// Todos 列出未结束的计划作为待办。instrumentID 为空时列出全部器具的待办，
434	// 否则只列该器具（器具不存在时报 ErrNotFound）。结果按计划日期从早到晚、
435	// 同日按器具编号排列。查询不产生任何使用记录或写盘。
436	func (l *Ledger) Todos(instrumentID string) ([]TodoItem, error) {
437		id := strings.TrimSpace(instrumentID)
438		if id != "" && l.findInstrument(id) == nil {
439			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
440		}
441		todayText := l.now().Format(DateLayout)
442		items := []TodoItem{}
443		for _, p := range l.data.Plans {
444			if !p.Open() {
445				continue
446			}
447			if id != "" && p.InstrumentID != id {
448				continue
449			}
450			inst := l.findInstrument(p.InstrumentID)
451			if inst == nil {
452				continue
453			}
454			items = append(items, TodoItem{
455				PlanNumber:     p.Number,
456				InstrumentID:   inst.ID,
457				InstrumentName: inst.Name,
458				Status:         inst.Status,
459				PlannedDate:    p.PlannedDate,
460				Note:           p.Note,
461				Marker:         planMarker(p.PlannedDate, todayText),
462			})
463		}
464		sort.Slice(items, func(i, j int) bool {
465			if items[i].PlannedDate != items[j].PlannedDate {
466				return items[i].PlannedDate < items[j].PlannedDate
467			}
468			return items[i].InstrumentID < items[j].InstrumentID
469		})
470		return items, nil
471	}
472	
473	// PlanView 是计划的完整视图，供按器具核对时展示当前与已结束计划、
474	// 改期记录和关联证书编号。
475	type PlanView struct {
476		Plan
477		Marker string `json:"marker"`
478	}
479	
480	// plansOf 返回某器具的全部计划（含已结束），按建立先后排列。
481	// 返回的是深拷贝（含改期历史）：调用方整理按器具查询或核对结果中的
482	// 计划与改期记录，不会回写台账，也不会影响此前或之后分别取得的其他结果。
483	func (l *Ledger) plansOf(id string) []Plan {
484		var out []Plan
485		for _, p := range l.data.Plans {
486			if p.InstrumentID == id {
487				out = append(out, clonePlan(p))
488			}
489		}
490		sort.SliceStable(out, func(i, j int) bool { return out[i].CreatedAt < out[j].CreatedAt })
491		return out
492	}
493	
494	// planViews 构造器具核对用的计划视图；标记仅对未结束计划有意义。
495	func (l *Ledger) planViews(id string, today time.Time) []PlanView {
496		todayText := today.Format(DateLayout)
497		plans := l.plansOf(id)
498		out := make([]PlanView, 0, len(plans))
499		for _, p := range plans {
500			v := PlanView{Plan: p}
501			if p.Open() {
502				v.Marker = planMarker(p.PlannedDate, todayText)
503			}
504			out = append(out, v)
505		}
506		return out
507	}
508	
509	// Plans 返回某器具的全部计划（含已结束），按建立先后排列；
510	// 器具不存在时报 ErrNotFound。返回的计划（含改期历史）都是独立展示副本：
511	// 调用方调换顺序、删改或追加记录或改动任何字段，只影响自己手中的结果，
512	// 不回写台账，也不影响此前或之后分别取得的操作结果与核对结果。查询不写盘。
513	func (l *Ledger) Plans(instrumentID string) ([]PlanView, error) {
514		id := strings.TrimSpace(instrumentID)
515		inst := l.findInstrument(id)
516		if inst == nil {
517			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
518		}
519		return l.planViews(id, l.now()), nil
520	}
521

