350			t.Fatalf("超差证书应能完成计划，err=%v plan=%+v", err, done)
351		}
352		// 但器具是否可用仍按状态、最近证书结论和有效期判断：超差仍被拒绝。
353		d, err := l.RequestUse("M-1")
354		if err != nil {
355			t.Fatalf("request use: %v", err)
356		}
357		if d.Allowed || !containsReason(d.Reasons, "超差") {
358			t.Fatalf("计划完成不应改变超差判定，得到 allowed=%v reasons=%v", d.Allowed, d.Reasons)
359		}
360		r, _ := l.Review("M-1")
361		if r.Latest == nil || r.Latest.Pass {
362			t.Fatal("最近证书仍应判超差")
363		}
364	}
